def entailed_types(triples):
    supers = {}
    for s, p, o in triples:
        if p == "subClassOf":
            supers.setdefault(s, set()).add(o)

    def above(cls):
        seen, stack = set(), [cls]
        while stack:
            for sup in supers.get(stack.pop(), ()):
                if sup not in seen:
                    seen.add(sup)
                    stack.append(sup)
        return seen

    out = set()
    for s, p, o in triples:
        if p != "type":
            continue
        for sup in above(o):
            if sup != o and (s, "type", sup) not in triples:
                out.add((s, "type", sup))
    return out
